from PIL import Image, ImageDraw, ImageFont
import numpy as np
from collections import deque
im=Image.open('chess_board.png').convert('RGB')
blacks={(0,0),(0,2),(0,3),(0,5),(1,1),(1,5),(1,6),(2,0),(2,2),(2,4),(3,3),(3,5),(3,6)}
cells=[]
for r in range(8):
  for c in range(8):
    color='b' if (r,c) in blacks else 'w'
    x0,y0=c*80,r*80
    arr=np.zeros((80,80),bool)
    for y in range(80):
      for x in range(80):
        p=im.getpixel((x0+x,y0+y))
        arr[y,x]= max(p)<100 if color=='b' else min(p)>200
    if arr.sum()<50: continue
    ys,xs=np.where(arr)
    arr=arr[ys.min():ys.max()+1, xs.min():xs.max()+1]
    cells.append((r,c,color,arr))

def fill(m):
    h,w=m.shape
    outside=np.zeros_like(m)
    dq=deque()
    for x in range(w):
        for y in [0,h-1]:
            if not m[y,x] and not outside[y,x]: outside[y,x]=True; dq.append((y,x))
    for y in range(h):
        for x in [0,w-1]:
            if not m[y,x] and not outside[y,x]: outside[y,x]=True; dq.append((y,x))
    while dq:
        y,x=dq.popleft()
        for dy,dx in [(1,0),(-1,0),(0,1),(0,-1)]:
            ny,nx=y+dy,x+dx
            if 0<=ny<h and 0<=nx<w and not m[ny,nx] and not outside[ny,nx]:
                outside[ny,nx]=True; dq.append((ny,nx))
    return ~outside

def render(ch, size, fontpath):
    font=ImageFont.truetype(fontpath, size)
    img=Image.new('L',(size*2,size*2),0)
    d=ImageDraw.Draw(img)
    d.text((size//2,size//2),ch,fill=255,font=font)
    a=np.array(img)>128
    ys,xs=np.where(a)
    return a[ys.min():ys.max()+1, xs.min():xs.max()+1]
def norm(a,shape):
    return np.array(Image.fromarray(a.astype(np.uint8)*255).resize((shape[1],shape[0]),Image.NEAREST))>128
names={0x2654:'K',0x2655:'Q',0x2656:'R',0x2657:'B',0x2658:'N',0x2659:'P',0x265A:'k',0x265B:'q',0x265C:'r',0x265D:'b',0x265E:'n',0x265F:'p'}
fonts=['/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf','/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf']
for r,c,color,tgt0 in cells:
    if color!='w': continue
    tgt=fill(tgt0)
    best=[]
    for cp,nm in names.items():
      for fi,fp in enumerate(fonts):
        for sz in [48,56,64,72,80]:
          m=norm(render(chr(cp),sz,fp),tgt.shape)
          iou=(m&tgt).sum()/(m|tgt).sum()
          best.append((iou,nm,fi,sz))
    best.sort(reverse=True)
    print(f'r{r}c{c} shape{tgt.shape}:', ' '.join(f'{nm}/f{fi}/{sz}:{iou:.3f}' for iou,nm,fi,sz in best[:6]))
